# framework-doctor PowerShell fixture tests: truthful states and survival paths.
param([ValidateSet(0,1,2,3,4,5,6,7,9)][int]$ProtectedSyncArm=0)
if (-not (Get-Command Assert -ErrorAction SilentlyContinue)) { . (Join-Path $PSScriptRoot '_HookHarness.ps1') }
$scripts=(Resolve-Path (Join-Path $PSScriptRoot '..\..\scripts')).Path
$doctorPs=Join-Path $scripts 'framework-doctor.ps1'
$script:SelfHost=(Get-Process -Id $PID).Path

function Put($Path,$Text,[bool]$Bom=$false){$parent=Split-Path -Parent $Path;if($parent){New-Item -ItemType Directory -Force $parent|Out-Null};[IO.File]::WriteAllText($Path,$Text,[Text.UTF8Encoding]::new($Bom))}
function Resolve-WindowsPowerShell{$onPath=Get-Command powershell.exe -CommandType Application -ErrorAction SilentlyContinue|Select-Object -First 1;if($onPath){return $onPath.Source};if($env:SystemRoot){$wellKnown=Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe';if(Test-Path -LiteralPath $wellKnown -PathType Leaf){return $wellKnown}};$null}
$winPs=Resolve-WindowsPowerShell

function Fixture{
    param([string]$Shell=$script:SelfHost,[bool]$Pending=$false,[bool]$MissingHook=$false,[bool]$HookArguments=$false,[bool]$CopilotPowerShell=$true,[string]$Template='java',[ValidateSet('maven','gradle','both')][string]$JavaBuild='maven',[string]$TargetRoot)
    $root=if($TargetRoot){$TargetRoot}else{Join-Path([IO.Path]::GetTempPath())('doctor-'+[guid]::NewGuid())}
    New-Item -ItemType Directory -Force (Join-Path $root '.claude/hooks'),(Join-Path $root '.github/hooks'),(Join-Path $root '.github/instructions'),(Join-Path $root 'scripts')|Out-Null
    Put (Join-Path $root '.claude/framework-version.json') ('{"template":"'+$Template+'","version":"0.32.0","applied":"2026-07-17","decimal":0.01,"exponent":1e01,"negativeExponent":1e-01}')
    $withEvidence=$PSBoundParameters.ContainsKey('Template')
    if($withEvidence-and$Template-eq'java'-and$JavaBuild-ne'gradle'){Put (Join-Path $root 'pom.xml') '<project xmlns="http://maven.apache.org/POM/4.0.0"><modelVersion>4.0.0</modelVersion><groupId>com.example</groupId><artifactId>app</artifactId><version>1.0.0</version></project>'}
    if($withEvidence-and$Template-eq'java'-and$JavaBuild-ne'maven'){Put (Join-Path $root 'build.gradle') "plugins { id 'java' }"}
    $claude="<!--`n  version: 0.32.0`n-->`n@.github/instructions/framework-rules.instructions.md`n# Fixture";if($Pending){$claude+="`nBOOTSTRAP_PENDING"};Put (Join-Path $root CLAUDE.md) $claude
    Put (Join-Path $root '.github/instructions/framework-rules.instructions.md') "---`napplyTo: `"**`"`n---`n# Verification Rules"
    $token=if($Shell-match'[\\/]'){('"'+$Shell+'"')}else{$Shell};$mode=if($HookArguments){' -Mode scan'}else{''};$command="$token -NoProfile -File .claude/hooks/guard.ps1$mode"
    Put (Join-Path $root '.claude/settings.json') (@{hooks=@{PreToolUse=@(@{hooks=@(@{command=$command})})}}|ConvertTo-Json -Depth 8)
    $copilot=if($CopilotPowerShell){'{"hooks":{"preToolUse":[{"powershell":"pwsh -NoProfile -File .claude\\hooks\\guard.ps1"}]}}'}else{'{"hooks":{"preToolUse":[]}}'};Put (Join-Path $root '.github/hooks/hooks.json') $copilot
    if(-not$MissingHook){Put (Join-Path $root '.claude/hooks/guard.ps1') ([char]0xFEFF+'# fixture')};Put (Join-Path $root '.claude/ai-audit.log') '';Put (Join-Path $root 'scripts/template-checks.ps1') ([char]0xFEFF+'exit 0');Copy-Item $doctorPs (Join-Path $root 'scripts/framework-doctor.ps1');$root
}
function Run($Path){$ef=[IO.Path]::GetTempFileName();try{$out=&$script:SelfHost -NoProfile -ExecutionPolicy Bypass -File $Path 2>$ef;[pscustomobject]@{Exit=$LASTEXITCODE;Out=($out-join"`n");Err=[IO.File]::ReadAllText($ef);ScriptPath=$Path}}finally{Remove-Item -Force $ef -ErrorAction SilentlyContinue}}
function RunPsHost($Exe,$Path){$ef=[IO.Path]::GetTempFileName();try{$out=&$Exe -NoProfile -ExecutionPolicy Bypass -File $Path 2>$ef;[pscustomobject]@{Exit=$LASTEXITCODE;Out=($out-join"`n");Err=[IO.File]::ReadAllText($ef);ScriptPath=$Path}}finally{Remove-Item -Force $ef -ErrorAction SilentlyContinue}}
$script:DoctorRowNames=@('Install state','Framework rules delivery','Protected-file sync','Bootstrap/adoption state','Wired hook shell','Hook liveness','Legacy Git-hook retirement','Retired framework residue','Hook files','Hook registration topology','Stack toolchain','Copilot surface','Layout and version integrity','Audit trail substrate')
function Parse-DoctorResult($Result){$text=$Result.Out-replace"`r",'';$parts=$text-split"`n`n",2;$rows=@{};foreach($line in($parts[0]-split"`n")){if($line-match'^\[(OK|MISSING|PENDING|CANT-VERIFY)\] (.+?) - (.*)$'){$name=$matches[2];Assert(-not$rows.ContainsKey($name))"duplicate doctor row '$name'";$rows[$name]=[pscustomobject]@{State=$matches[1];Name=$name;Detail=$matches[3]}}};$actual=@($rows.Keys|Sort-Object);$expected=@($script:DoctorRowNames|Sort-Object);Assert(($actual-join'|')-eq($expected-join'|'))"doctor row names differ: actual=$($actual-join',') expected=$($expected-join',')";$ok=@($rows.Values|Where-Object State -eq OK).Count;$missing=@($rows.Values|Where-Object State -eq MISSING).Count;$summary=[regex]::Match($text,'Script-verifiable checks: (\d+) ok / (\d+) missing\.');Assert $summary.Success "doctor summary absent: $text";Assert([int]$summary.Groups[1].Value-eq$ok)"summary ok mismatch";Assert([int]$summary.Groups[2].Value-eq$missing)"summary missing mismatch";$expectedExit=if($missing-gt0){1}else{0};Assert($Result.Exit-eq$expectedExit)"doctor exit=$($Result.Exit), expected=$expectedExit";$canaries=if($parts.Count-gt1){$parts[1]}else{''};[pscustomobject]@{Rows=$rows;Ok=$ok;Missing=$missing;Canaries=$canaries}}
function Get-StackCanary($Parsed){$m=[regex]::Match($Parsed.Canaries,'(?m)^\[CANT-VERIFY\] Agent-host stack toolchain - .+$');Assert $m.Success 'stack canary absent';$m.Value}
function New-ToolProbeBin([bool]$Copilot=$true){$bin=Join-Path([IO.Path]::GetTempPath())('doctor-tools-'+[guid]::NewGuid());New-Item -ItemType Directory -Force $bin|Out-Null;if($Copilot){Put (Join-Path $bin copilot.cmd) "@exit /b 0`r`n"};$bin}
function Add-FakeToolCommands($Bin,[string[]]$Names){foreach($name in $Names){Put (Join-Path $Bin($name+'.cmd')) "@exit /b 0`r`n"}}

Reset-Tests
$wellKnown=if($env:SystemRoot){Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'}else{$null}
if($wellKnown-and(Test-Path -LiteralPath $wellKnown -PathType Leaf)){It 'Windows PowerShell resolver falls back to SystemRoot when PATH cannot resolve it' {$old=$env:PATH;try{$env:PATH=[IO.Path]::GetTempPath();Assert(-not(Get-Command powershell.exe -CommandType Application -ErrorAction SilentlyContinue))'fixture still resolves powershell.exe';$resolved=Resolve-WindowsPowerShell;Assert($resolved-eq$wellKnown)"resolved '$resolved'";&$resolved -NoProfile -Command 'exit 0';Assert($LASTEXITCODE-eq0)'resolved host unusable'}finally{$env:PATH=$old}}}
It 'healthy fixture exits zero and exposes the complete boundary' {$r=Fixture;try{$p=Parse-DoctorResult(Run(Join-Path $r 'scripts/framework-doctor.ps1'));Assert($p.Rows['Install state'].State-eq'OK')'install state';Assert($p.Rows['Hook registration topology'].State-eq'OK')'topology';Assert($p.Rows['Retired framework residue'].State-eq'OK')'residue';Assert($p.Canaries-match'Enforcement is only FULL')'false-full boundary'}finally{Remove-Item -Recurse -Force $r}}

function New-LegacyFixture{$r=Fixture;&git -C $r init -q;Assert($LASTEXITCODE-eq0)'git init failed';$r}
function Set-PreCommit($Root,$Text){Put (Join-Path $Root '.git/hooks/pre-commit') $Text}
$legacyPs=@'
#!/bin/sh
repo_root=$(git rev-parse --show-toplevel) || exit 1
exec pwsh -NoProfile -File "$repo_root/scripts/setup-git-hooks.ps1" -Target "$repo_root" -Scan
'@
$legacySh=@'
#!/bin/sh
repo_root=$(git rev-parse --show-toplevel) || exit 1
exec bash "$repo_root/scripts/setup-git-hooks.sh" --target "$repo_root" --scan
'@
It 'legacy PowerShell pre-commit with complete closure is pending' {$r=New-LegacyFixture;try{Set-PreCommit $r $legacyPs;Put (Join-Path $r 'scripts/setup-git-hooks.ps1')([char]0xFEFF+'# helper');$row=(Parse-DoctorResult(Run(Join-Path $r 'scripts/framework-doctor.ps1'))).Rows['Legacy Git-hook retirement'];Assert($row.State-eq'PENDING'-and$row.Detail-match'PowerShell legacy')"$($row.State): $($row.Detail)"}finally{Remove-Item -Recurse -Force $r}}
It 'semicolon-terminated legacy PowerShell helper reference is pending' {$r=New-LegacyFixture;try{Set-PreCommit $r "& scripts/setup-git-hooks.ps1;`n";Put (Join-Path $r 'scripts/setup-git-hooks.ps1')([char]0xFEFF+'# helper');$row=(Parse-DoctorResult(Run(Join-Path $r 'scripts/framework-doctor.ps1'))).Rows['Legacy Git-hook retirement'];Assert($row.State-eq'PENDING'-and$row.Detail-match'PowerShell legacy')"$($row.State): $($row.Detail)"}finally{Remove-Item -Recurse -Force $r}}
if($winPs){It 'legacy-hook classification executes under Windows PowerShell 5.1' {$r=New-LegacyFixture;try{Set-PreCommit $r $legacyPs;Put (Join-Path $r 'scripts/setup-git-hooks.ps1')([char]0xFEFF+'# helper');$row=(Parse-DoctorResult(RunPsHost $winPs(Join-Path $r 'scripts/framework-doctor.ps1'))).Rows['Legacy Git-hook retirement'];Assert($row.State-eq'PENDING')"$($row.State): $($row.Detail)"}finally{Remove-Item -Recurse -Force $r}}}
It 'legacy Bash pre-commit with closure is degraded unmaintained and pending' {$r=New-LegacyFixture;try{Set-PreCommit $r $legacySh;Put (Join-Path $r 'scripts/setup-git-hooks.sh')'# helper';Put (Join-Path $r '.claude/hooks/guard.sh')'# guard';$row=(Parse-DoctorResult(Run(Join-Path $r 'scripts/framework-doctor.ps1'))).Rows['Legacy Git-hook retirement'];Assert($row.State-eq'PENDING'-and$row.Detail-match'Bash/degraded and unmaintained')"$($row.State): $($row.Detail)"}finally{Remove-Item -Recurse -Force $r}}
It 'legacy hook with missing dependency is MISSING' {$r=New-LegacyFixture;try{Set-PreCommit $r $legacyPs;$row=(Parse-DoctorResult(Run(Join-Path $r 'scripts/framework-doctor.ps1'))).Rows['Legacy Git-hook retirement'];Assert($row.State-eq'MISSING'-and$row.Detail-match'setup-git-hooks.ps1')"$($row.State): $($row.Detail)"}finally{Remove-Item -Recurse -Force $r}}
It 'orphan helper remains visible without a hook' {$r=New-LegacyFixture;try{Put (Join-Path $r 'scripts/setup-git-hooks.ps1')([char]0xFEFF+'# orphan');$row=(Parse-DoctorResult(Run(Join-Path $r 'scripts/framework-doctor.ps1'))).Rows['Legacy Git-hook retirement'];Assert($row.State-eq'PENDING'-and$row.Detail-match'remain without a default hook')"$($row.State): $($row.Detail)"}finally{Remove-Item -Recurse -Force $r}}
It 'contained repository without hook or helpers is clean' {$r=New-LegacyFixture;try{$row=(Parse-DoctorResult(Run(Join-Path $r 'scripts/framework-doctor.ps1'))).Rows['Legacy Git-hook retirement'];Assert($row.State-eq'OK'-and$row.Detail-match'no default pre-commit hook')"$($row.State): $($row.Detail)"}finally{Remove-Item -Recurse -Force $r}}
It 'nested target inside an ancestor worktree is CANT-VERIFY' {$parent=Join-Path([IO.Path]::GetTempPath())('doctor-parent-'+[guid]::NewGuid());$r=Join-Path $parent 'nested';try{New-Item -ItemType Directory -Force $parent|Out-Null;&git -C $parent init -q;Assert($LASTEXITCODE-eq0)'git init failed';Fixture -TargetRoot $r|Out-Null;$row=(Parse-DoctorResult(Run(Join-Path $r 'scripts/framework-doctor.ps1'))).Rows['Legacy Git-hook retirement'];Assert($row.State-eq'CANT-VERIFY'-and$row.Detail-match'nested, bare, or external')"$($row.State): $($row.Detail)"}finally{Remove-Item -Recurse -Force $parent -ErrorAction SilentlyContinue}}
It 'Husky ownership is report-only' {$r=New-LegacyFixture;try{New-Item -ItemType Directory (Join-Path $r .husky)|Out-Null;$row=(Parse-DoctorResult(Run(Join-Path $r 'scripts/framework-doctor.ps1'))).Rows['Legacy Git-hook retirement'];Assert($row.State-eq'CANT-VERIFY'-and$row.Detail-match'consumer-owned \.husky')"$($row.State): $($row.Detail)"}finally{Remove-Item -Recurse -Force $r}}
It 'unrelated default hook is OK and untouched' {$r=New-LegacyFixture;try{Set-PreCommit $r "#!/bin/sh`nexit 0`n";$path=Join-Path $r '.git/hooks/pre-commit';$before=[IO.File]::ReadAllText($path);$row=(Parse-DoctorResult(Run(Join-Path $r 'scripts/framework-doctor.ps1'))).Rows['Legacy Git-hook retirement'];Assert($row.State-eq'OK')"$($row.State)";Assert([IO.File]::ReadAllText($path)-ceq$before)'hook changed'}finally{Remove-Item -Recurse -Force $r}}
It 'custom core.hooksPath is never traversed' {$r=New-LegacyFixture;try{&git -C $r config core.hooksPath ..\outside-hooks;Assert($LASTEXITCODE-eq0)'config failed';$row=(Parse-DoctorResult(Run(Join-Path $r 'scripts/framework-doctor.ps1'))).Rows['Legacy Git-hook retirement'];Assert($row.State-eq'CANT-VERIFY'-and$row.Detail-match'was not followed')"$($row.State): $($row.Detail)"}finally{Remove-Item -Recurse -Force $r}}

$retiredPaths=@('.claude/hooks/audit-trail.sh','.claude/hooks/boy-scout-check.sh','.claude/hooks/guard.sh','.claude/hooks/post-write.sh','.claude/hooks/route-prompt.sh','.claude/hooks/session-start.sh','scripts/build-architecture-html.sh','scripts/ci/bitbucket-pipelines.example.yml','scripts/docs-sync-check.sh','scripts/framework-doctor.sh','scripts/hazard-check.sh','scripts/metrics.sh','scripts/setup-git-hooks.ps1','scripts/setup-git-hooks.sh','scripts/template-checks.sh','scripts/test-weakening-scan.sh','scripts/warehouse-map-check.sh','scripts/wiki-check.sh')
It 'all 18 v0.83 retired paths remain visible as residue' {Assert($retiredPaths.Count-eq18)"count=$($retiredPaths.Count)";$r=Fixture;try{foreach($path in $retiredPaths){Put (Join-Path $r $path)'# residue'};$row=(Parse-DoctorResult(Run(Join-Path $r 'scripts/framework-doctor.ps1'))).Rows['Retired framework residue'];Assert($row.State-eq'PENDING')"$($row.State): $($row.Detail)";foreach($path in $retiredPaths){Assert($row.Detail.Contains($path))"omitted $path"}}finally{Remove-Item -Recurse -Force $r}}
It 'the retired architecture generator is visible as residue' {$r=Fixture;try{Put (Join-Path $r 'scripts/build-architecture-html.ps1')([char]0xFEFF+'# residue');$row=(Parse-DoctorResult(Run(Join-Path $r 'scripts/framework-doctor.ps1'))).Rows['Retired framework residue'];Assert($row.State-eq'PENDING')"$($row.State): $($row.Detail)";Assert($row.Detail.Contains('scripts/build-architecture-html.ps1'))'retired generator omitted from residue detail'}finally{Remove-Item -Recurse -Force $r}}
It 'unreadable retired residue is CANT-VERIFY' {$r=Fixture;$stream=$null;try{$path=Join-Path $r 'scripts/wiki-check.sh';Put $path '# locked';$stream=[IO.File]::Open($path,[IO.FileMode]::Open,[IO.FileAccess]::ReadWrite,[IO.FileShare]::None);$row=(Parse-DoctorResult(Run(Join-Path $r 'scripts/framework-doctor.ps1'))).Rows['Retired framework residue'];Assert($row.State-eq'CANT-VERIFY'-and$row.Detail.Contains('scripts/wiki-check.sh'))"$($row.State): $($row.Detail)"}finally{if($stream){$stream.Dispose()};Remove-Item -Recurse -Force $r}}
if([Environment]::OSVersion.Platform-eq[PlatformID]::Win32NT){It 'reparse retired residue is CANT-VERIFY and not followed' {$r=Fixture;$outside=Join-Path([IO.Path]::GetTempPath())('doctor-outside-'+[guid]::NewGuid());try{New-Item -ItemType Directory $outside|Out-Null;Put (Join-Path $outside 'bitbucket-pipelines.example.yml')'# outside';New-Item -ItemType Junction -Path (Join-Path $r 'scripts/ci') -Target $outside|Out-Null;$row=(Parse-DoctorResult(Run(Join-Path $r 'scripts/framework-doctor.ps1'))).Rows['Retired framework residue'];Assert($row.State-eq'CANT-VERIFY'-and$row.Detail.Contains('scripts/ci/bitbucket-pipelines.example.yml'))"$($row.State): $($row.Detail)"}finally{Remove-Item -Recurse -Force $r,$outside}}}

It 'missing framework-rules import is honest' {$r=Fixture -Pending $true;try{$path=Join-Path $r CLAUDE.md;Put $path([IO.File]::ReadAllText($path)-replace'(?m)^@\.github/instructions/framework-rules\.instructions\.md\r?\n','');$p=Parse-DoctorResult(Run(Join-Path $r 'scripts/framework-doctor.ps1'));Assert($p.Rows['Framework rules delivery'].State-eq'MISSING')'delivery row'}finally{Remove-Item -Recurse -Force $r}}
function Assert-ProtectedSync($Root,$State,$Detail,$Delivery='OK'){$p=Parse-DoctorResult(Run(Join-Path $Root 'scripts/framework-doctor.ps1'));$row=$p.Rows['Protected-file sync'];Assert($row.State-eq$State)"state=$($row.State) expected=$State";Assert($row.Detail-eq$Detail)"detail='$($row.Detail)'";Assert($p.Rows['Framework rules delivery'].State-eq$Delivery)"delivery=$($p.Rows['Framework rules delivery'].State)"}
function Add-Headings($Root,[string[]]$Headings){$path=Join-Path $Root CLAUDE.md;Put $path([IO.File]::ReadAllText($path)+"`n"+(($Headings|ForEach-Object{"## $_"})-join"`n"))}
function New-SyncFixture([ValidateSet('migrated','one','all','boy-scout','no-import','no-claude','empty-claude','empty-list','agents-inline')]$Case){$r=Fixture -Pending $true;switch($Case){one{Add-Headings $r @('Leanness')}all{Add-Headings $r @('Verification Rules','Leanness','SOLID','Agentic Workflow')}boy-scout{Add-Headings $r @('Boy Scout Rule')}no-import{$p=Join-Path $r CLAUDE.md;Put $p([IO.File]::ReadAllText($p)-replace'(?m)^@\.github/instructions/framework-rules\.instructions\.md\r?\n','')}no-claude{Remove-Item(Join-Path $r CLAUDE.md)-Force}empty-claude{Put(Join-Path $r CLAUDE.md)''}agents-inline{Put(Join-Path $r AGENTS.md)"# Project`n## Leanness`nstale copy`n"}empty-list{$p=Join-Path $r 'scripts/framework-doctor.ps1';$text=[IO.File]::ReadAllText($p);$mut=$text.Replace("`$frameworkHeadings = @('Verification Rules', 'Leanness', 'SOLID', 'Agentic Workflow')",'$frameworkHeadings = @()');Assert($mut-ne$text)'mutation missed';Put $p $mut $true}};$r}
$migrated='migrated - the carrier is authoritative.';$prefix='migration incomplete - these sections duplicate the carrier and may conflict:';$suffix='Fix: delete them from the named file.';$inspection='framework heading inspection is incomplete; protected-file migration state cannot be verified.'
function It-Sync($Arm,$Name,$Body){if($ProtectedSyncArm-eq0-or$ProtectedSyncArm-eq$Arm){It $Name $Body}}
It-Sync 1 'Protected sync migrated' {$r=New-SyncFixture migrated;try{Assert-ProtectedSync $r OK $migrated}finally{Remove-Item -Recurse -Force $r}}
It-Sync 2 'Protected sync one inline heading' {$r=New-SyncFixture one;try{Assert-ProtectedSync $r PENDING "$prefix Leanness (CLAUDE.md). $suffix"}finally{Remove-Item -Recurse -Force $r}}
It-Sync 3 'Protected sync all inline headings' {$r=New-SyncFixture all;try{Assert-ProtectedSync $r PENDING "$prefix Verification Rules (CLAUDE.md), Leanness (CLAUDE.md), SOLID (CLAUDE.md), Agentic Workflow (CLAUDE.md). $suffix"}finally{Remove-Item -Recurse -Force $r}}
It-Sync 4 'Protected sync ignores Boy Scout heading' {$r=New-SyncFixture boy-scout;try{Assert-ProtectedSync $r OK $migrated}finally{Remove-Item -Recurse -Force $r}}
It-Sync 5 'Protected sync missing import defers' {$r=New-SyncFixture no-import;try{Assert-ProtectedSync $r OK 'deferred to Framework rules delivery.' MISSING}finally{Remove-Item -Recurse -Force $r}}
It-Sync 6 'Protected sync absent CLAUDE is missing' {$r=New-SyncFixture no-claude;try{Assert-ProtectedSync $r MISSING 'CLAUDE.md is absent; protected-file migration state cannot be inspected.' MISSING}finally{Remove-Item -Recurse -Force $r}}
It-Sync 7 'Protected sync empty heading list fails closed' {$r=New-SyncFixture empty-list;try{Assert-ProtectedSync $r MISSING $inspection}finally{Remove-Item -Recurse -Force $r}}
It-Sync 9 'Protected sync empty CLAUDE still emits row' {$r=New-SyncFixture empty-claude;try{Assert-ProtectedSync $r OK 'deferred to Framework rules delivery.' MISSING}finally{Remove-Item -Recurse -Force $r}}
It-Sync 10 'Protected sync names inline headings moved into AGENTS.md' {$r=New-SyncFixture agents-inline;try{Assert-ProtectedSync $r PENDING "$prefix Leanness (AGENTS.md). $suffix"}finally{Remove-Item -Recurse -Force $r}}
if($ProtectedSyncArm-ne0){exit(Write-TestSummary 'FrameworkDoctor.Tests')}

It 'pending adoption is not broken' {$r=Fixture -Pending $true;try{Put(Join-Path $r '.claude/adoption-pending.json')'{}';$p=Parse-DoctorResult(Run(Join-Path $r 'scripts/framework-doctor.ps1'));Assert($p.Rows['Bootstrap/adoption state'].State-eq'PENDING')'pending';Assert($p.Rows['Stack toolchain'].State-eq'PENDING')'toolchain'}finally{Remove-Item -Recurse -Force $r}}
It 'missing hook file exits one' {$r=Fixture -MissingHook $true;try{$p=Parse-DoctorResult(Run(Join-Path $r 'scripts/framework-doctor.ps1'));Assert($p.Rows['Hook files'].State-eq'MISSING')'hook files'}finally{Remove-Item -Recurse -Force $r}}
It 'wired shell reports bare existing and missing states' {foreach($case in @(@{Shell='doctor-shell-bare';State='CANT-VERIFY';Needle='portable bare interpreter'},@{Shell=[IO.Path]::GetTempFileName();State='OK';Needle='wired interpreter paths exist'},@{Shell=Join-Path([IO.Path]::GetTempPath())'missing-doctor/interpreter.exe';State='MISSING';Needle='restore portable bare-name wiring'})){$r=Fixture -Shell $case.Shell -Pending $true;try{$row=(Parse-DoctorResult(Run(Join-Path $r 'scripts/framework-doctor.ps1'))).Rows['Wired hook shell'];Assert($row.State-eq$case.State)"$($case.Shell): $($row.State)";Assert($row.Detail-match$case.Needle)"$($row.Detail)"}finally{Remove-Item -Recurse -Force $r;if($case.State-eq'OK'){Remove-Item $case.Shell -Force -ErrorAction SilentlyContinue}}}}
if($winPs){It 'doctor runs under Windows PowerShell 5.1' {$r=Fixture;try{$p=Parse-DoctorResult(RunPsHost $winPs(Join-Path $r 'scripts/framework-doctor.ps1'));Assert($p.Rows['Install state'].State-eq'OK')'5.1 output'}finally{Remove-Item -Recurse -Force $r}}}
It 'retired Bash registrations are MISSING without parser probing' {$cases=@(@{Settings='{"hooks":{"PreToolUse":[{"hooks":[{"command":"bash .claude/hooks/guard.sh"}]}]}}';Copilot=$null},@{Settings='{"hooks":{"PreToolUse":[{"hooks":[{"command":"\"C:\\\\Git\\\\bash.exe\" .claude/hooks/guard.sh"}]}]}}';Copilot=$null},@{Settings=$null;Copilot='{"hooks":{"preToolUse":[{"bash":".claude/hooks/guard.sh"}]}}'});Assert($cases.Count-gt0)'cases empty';foreach($case in $cases){$r=Fixture -Pending $true;try{Put(Join-Path $r '.claude/hooks/guard.sh')'# residue';if($case.Settings){Put(Join-Path $r '.claude/settings.json')$case.Settings};if($case.Copilot){Put(Join-Path $r '.github/hooks/hooks.json')$case.Copilot};$row=(Parse-DoctorResult(Run(Join-Path $r 'scripts/framework-doctor.ps1'))).Rows['Hook registration topology'];Assert($row.State-eq'MISSING'-and$row.Detail-match'retired Bash')"$($row.State): $($row.Detail)"}finally{Remove-Item -Recurse -Force $r}}}
It 'Copilot visibility is process-scoped' {$old=$env:PATH;try{foreach($present in @($true,$false)){$r=Fixture -Pending $true;$bin=New-ToolProbeBin $present;try{$env:PATH=$bin;$row=(Parse-DoctorResult(Run(Join-Path $r 'scripts/framework-doctor.ps1'))).Rows['Copilot surface'];Assert(($row.Detail-match'CLI is available')-eq$present)"present=$present detail=$($row.Detail)"}finally{Remove-Item -Recurse -Force $r,$bin}}}finally{$env:PATH=$old}}
It 'unreadable and invalid hook configuration stays explicit' {$r=Fixture -Pending $true;try{$doc=Join-Path $r 'scripts/framework-doctor.ps1';$settings=[IO.File]::ReadAllText((Join-Path $r '.claude/settings.json'));$text=[IO.File]::ReadAllText($doc);$mut=$text.Replace('$copilotReadFailed = $false','$copilotReadFailed = $true');Assert($mut-ne$text)'Copilot mutation';Put $doc $mut $true;$p=Parse-DoctorResult(Run $doc);foreach($name in @('Hook files','Hook registration topology','Copilot surface')){Assert($p.Rows[$name].State-eq'CANT-VERIFY')"Copilot $name"};Copy-Item $doctorPs $doc -Force;$text=[IO.File]::ReadAllText($doc);$mut=$text.Replace('$settingsReadFailed = $false','$settingsReadFailed = $true');Assert($mut-ne$text)'settings mutation';Put $doc $mut $true;$p=Parse-DoctorResult(Run $doc);foreach($name in @('Wired hook shell','Hook files','Hook registration topology')){Assert($p.Rows[$name].State-eq'CANT-VERIFY')"settings $name"};Copy-Item $doctorPs $doc -Force;foreach($bad in @('{"command":"pwsh .claude/hooks/guard.ps1" junk','{"command":"pwsh .claude/hooks/guard.ps1",}',"{'command':'pwsh .claude/hooks/guard.ps1'}",'{"command":"pwsh .claude/hooks/guard.ps1","probe":NaN}','{"command":"pwsh .claude/hooks/guard.ps1","probe":01}','{"Command":"pwsh .claude/hooks/guard.ps1"}')){Put(Join-Path $r '.claude/settings.json')$bad;$p=Parse-DoctorResult(Run $doc);Assert($p.Rows['Wired hook shell'].State-eq'MISSING')"settings accepted: $bad"};Put(Join-Path $r '.claude/settings.json')$settings;foreach($bad in @('{"hooks":{"preToolUse":[{"powershell":"pwsh .claude/hooks/guard.ps1"}]} junk','{"hooks":{"preToolUse":[]},}',"{'hooks':{'preToolUse':[]}}",'{"hooks":{"preToolUse":[]},"probe":NaN}','{"hooks":{"preToolUse":[]},"probe":01}')){Put(Join-Path $r '.github/hooks/hooks.json')$bad;$p=Parse-DoctorResult(Run $doc);foreach($name in @('Hook files','Hook registration topology','Copilot surface')){Assert($p.Rows[$name].State-eq'MISSING')"Copilot accepted $bad ($name)"}}}finally{Remove-Item -Recurse -Force $r}}
It 'liveness covers absent empty whitespace and present' {$r=Fixture -Pending $true;try{foreach($world in @(@{Create=$false;Text='';State='CANT-VERIFY'},@{Create=$true;Text='';State='CANT-VERIFY'},@{Create=$true;Text='   ';State='CANT-VERIFY'},@{Create=$true;Text='2026-07-31T12:34:56Z';State='OK'})){$path=Join-Path $r '.claude/.state/last-session-start';Remove-Item $path -Force -ErrorAction SilentlyContinue;if($world.Create){Put $path $world.Text};$row=(Parse-DoctorResult(Run(Join-Path $r 'scripts/framework-doctor.ps1'))).Rows['Hook liveness'];Assert($row.State-eq$world.State)"'$($world.Text)' => $($row.State)"}}finally{Remove-Item -Recurse -Force $r}}
It 'hook registration resolves arguments and every minified command' {$r=Fixture -Pending $true -HookArguments $true;try{$p=Parse-DoctorResult(Run(Join-Path $r 'scripts/framework-doctor.ps1'));Assert($p.Rows['Hook files'].State-eq'OK')'args';Put(Join-Path $r '.claude/settings.json')'{"hooks":{"PreToolUse":[{"hooks":[{"command":"pwsh .claude/hooks/guard.ps1 -Mode scan"},{"command":"pwsh .claude/hooks/missing.ps1 -Mode scan"}]}]}}';$p=Parse-DoctorResult(Run(Join-Path $r 'scripts/framework-doctor.ps1'));Assert($p.Rows['Hook files'].State-eq'MISSING')'minified second command'}finally{Remove-Item -Recurse -Force $r}}
It 'mirror checker status maps 0 3 2 and 1 honestly' {$r=Fixture;try{foreach($world in @(@{Code=0;State='OK'},@{Code=3;State='MISSING'},@{Code=2;State='CANT-VERIFY'},@{Code=1;State='CANT-VERIFY'})){Put(Join-Path $r 'scripts/template-checks.ps1')([char]0xFEFF+"exit $($world.Code)");$row=(Parse-DoctorResult(Run(Join-Path $r 'scripts/framework-doctor.ps1'))).Rows['Layout and version integrity'];Assert($row.State-eq$world.State)"$($world.Code) => $($row.State)";if($world.Code-eq3){Assert($row.Detail-ceq'template-checks reported integrity findings. Run it directly and follow its exact findings.')'finding detail'}elseif($world.Code-ne0){Assert($row.Detail.Contains("did not complete (exit $($world.Code))")-and$row.Detail.Contains('UNKNOWN rather than missing'))'unable detail'}}}finally{Remove-Item -Recurse -Force $r}}

It 'toolchain covers every build tool and present or absent tools' {$old=$env:PATH;$oldJava=$env:JAVA_HOME;try{$env:JAVA_HOME='';foreach($build in @('maven','gradle','both')){$tools=if($build-eq'maven'){@('mvn','java')}elseif($build-eq'gradle'){@('gradle','java')}else{@('mvn','gradle','java')};foreach($present in @($true,$false)){$r=Fixture -Template java -JavaBuild $build;$bin=New-ToolProbeBin;try{if($present){Add-FakeToolCommands $bin $tools};$env:PATH=$bin;$p=Parse-DoctorResult(Run(Join-Path $r 'scripts/framework-doctor.ps1'));$expected=if($present){'OK'}else{'MISSING'};Assert($p.Rows['Stack toolchain'].State-eq$expected)"$build/$present";Assert($p.Rows['Stack toolchain'].Detail-match'this doctor process environment')'boundary';if($present){$needle=if($build-eq'maven'){'starts with "## mvn test-compile failed".'}elseif($build-eq'gradle'){'starts with "## gradle testClasses failed".'}else{'starts with "## mvn test-compile failed" or "## gradle testClasses failed".'};Assert((Get-StackCanary $p).Contains($needle))"canary $build"}}finally{Remove-Item -Recurse -Force $r,$bin}}}}finally{$env:PATH=$old;$env:JAVA_HOME=$oldJava}}
It 'toolchain accepts a committed wrapper instead of a build tool on PATH but still needs a JDK' {$old=$env:PATH;$oldJava=$env:JAVA_HOME;try{$env:JAVA_HOME='';foreach($case in @(@{Build='maven';Wrapper='mvnw.cmd';Label='Maven'},@{Build='gradle';Wrapper='gradlew.bat';Label='Gradle'})){$r=Fixture -Template java -JavaBuild $case.Build;$bin=New-ToolProbeBin;try{Put(Join-Path $r $case.Wrapper)"@exit /b 0`r`n";Add-FakeToolCommands $bin @('java');$env:PATH=$bin;$row=(Parse-DoctorResult(Run(Join-Path $r 'scripts/framework-doctor.ps1'))).Rows['Stack toolchain'];Assert($row.State-eq'OK'-and$row.Detail.Contains("Java ($($case.Label))"))"wrapper $($case.Label): $($row.State) $($row.Detail)";Remove-Item(Join-Path $bin 'java.cmd')-Force;$row=(Parse-DoctorResult(Run(Join-Path $r 'scripts/framework-doctor.ps1'))).Rows['Stack toolchain'];Assert($row.State-eq'MISSING'-and$row.Detail-match'absent from this doctor process environment: java;')"no JDK $($case.Label): $($row.State) $($row.Detail)"}finally{Remove-Item -Recurse -Force $r,$bin}}}finally{$env:PATH=$old;$env:JAVA_HOME=$oldJava}}
It 'toolchain excludes generated evidence but includes hidden source' {$old=$env:PATH;$oldJava=$env:JAVA_HOME;try{$env:JAVA_HOME='';$r=Fixture -Template java;$bin=New-ToolProbeBin;try{Remove-Item(Join-Path $r pom.xml)-Force;Put(Join-Path $r 'TARGET/classes/pom.xml')'<project/>';Put(Join-Path $r 'BUILD/build.gradle')"plugins { id 'java' }";Put(Join-Path $r 'NODE_MODULES/pkg/pom.xml')'<project/>';Put(Join-Path $r '.GRADLE/settings.gradle')'';$env:PATH=$bin;$p=Parse-DoctorResult(Run(Join-Path $r 'scripts/framework-doctor.ps1'));Assert($p.Rows['Stack toolchain'].State-eq'OK'-and$p.Rows['Stack toolchain'].Detail-match'not applicable')'generated'}finally{Remove-Item -Recurse -Force $r,$bin};$r=Fixture -Template java;$bin=New-ToolProbeBin;try{New-Item -ItemType Directory(Join-Path $r .src)|Out-Null;Move-Item(Join-Path $r pom.xml)(Join-Path $r '.src/pom.xml');Add-FakeToolCommands $bin @('mvn','java');$env:PATH=$bin;$p=Parse-DoctorResult(Run(Join-Path $r 'scripts/framework-doctor.ps1'));Assert($p.Rows['Stack toolchain'].State-eq'OK'-and$p.Rows['Stack toolchain'].Detail.Contains('Java (Maven)'))'hidden'}finally{Remove-Item -Recurse -Force $r,$bin}}finally{$env:PATH=$old;$env:JAVA_HOME=$oldJava}}
It 'strict stamp rejects malformed and missing template forms' {$cases=@(@{Text='junk {"template":"java"}';Needle='invalid JSON'},@{Text='{"template":"java",}';Needle='invalid JSON'},@{Text='{/*comment*/"template":"java"}';Needle='invalid JSON'},@{Text='{template:"java"}';Needle='invalid JSON'},@{Text='{"template":"java","probe":NaN}';Needle='invalid JSON'},@{Text='{"template":"java","probe":01}';Needle='invalid JSON'},@{Text='{"Template":"java"}';Needle='lacks the required non-empty string'},@{Text='{}';Needle='lacks the required non-empty string'},@{Text='[{"template":"java"}]';Needle='lacks the required non-empty string'},@{Text='{"template":"   "}';Needle='lacks the required non-empty string'},@{Text='{"template":"foo"}';Needle='unsupported template'});Assert($cases.Count-eq11)"cases=$($cases.Count)";foreach($case in $cases){$r=Fixture -Pending $true;try{Put(Join-Path $r '.claude/framework-version.json')$case.Text;$x=Run(Join-Path $r 'scripts/framework-doctor.ps1');$line=[regex]::Match($x.Out,'(?m)^\[MISSING\] Install state - .+$').Value;Assert($x.Exit-eq1-and$line-match[regex]::Escape($case.Needle))"$($case.Text): $line"}finally{Remove-Item -Recurse -Force $r}}}
It 'unreadable stamp is CANT-VERIFY' {$r=Fixture -Pending $true;try{$doc=Join-Path $r 'scripts/framework-doctor.ps1';$text=[IO.File]::ReadAllText($doc);$mut=$text.Replace('$stampReadFailed = $false','$stampReadFailed = $true');Assert($mut-ne$text)'mutation';Put $doc $mut $true;$x=Run $doc;Assert($x.Exit-eq0-and$x.Out-match'\[CANT-VERIFY\] Install state - \.claude/framework-version\.json exists but could not be read')"$($x.Out)"}finally{Remove-Item -Recurse -Force $r}}
It 'a settings file alone selects Gradle and a pom.xml beside it adds Maven' {$old=$env:PATH;$oldJava=$env:JAVA_HOME;$r=Fixture -Template java -JavaBuild gradle;$bin=New-ToolProbeBin;try{$env:JAVA_HOME='';Remove-Item(Join-Path $r build.gradle)-Force;Put(Join-Path $r 'settings.gradle.kts')'rootProject.name = "app"';Add-FakeToolCommands $bin @('gradle','java');$env:PATH=$bin;$row=(Parse-DoctorResult(Run(Join-Path $r 'scripts/framework-doctor.ps1'))).Rows['Stack toolchain'];Assert($row.State-eq'OK'-and$row.Detail.Contains('Java (Gradle)'))"settings only => $($row.State) $($row.Detail)";Put(Join-Path $r 'pom.xml')'<project/>';$row=(Parse-DoctorResult(Run(Join-Path $r 'scripts/framework-doctor.ps1'))).Rows['Stack toolchain'];Assert($row.State-eq'MISSING'-and$row.Detail-match'absent from this doctor process environment: mvn;')"pom beside => $($row.State) $($row.Detail)"}finally{$env:PATH=$old;$env:JAVA_HOME=$oldJava;Remove-Item -Recurse -Force $r,$bin}}
It 'incomplete marker scan is CANT-VERIFY' {$r=Fixture -Template java;try{$doc=Join-Path $r 'scripts/framework-doctor.ps1';$text=[IO.File]::ReadAllText($doc);$mut=$text.Replace('$markerScanFailed = $false','$markerScanFailed = $true');Assert($mut-ne$text)'mutation';Put $doc $mut $true;$p=Parse-DoctorResult(Run $doc);Assert($p.Rows['Stack toolchain'].State-eq'CANT-VERIFY')"$($p.Rows['Stack toolchain'].State)";Assert((Get-StackCanary $p)-match'cannot be verified')'canary'}finally{Remove-Item -Recurse -Force $r}}
It 'pinned canary strings exist in PowerShell hooks' {$text=[IO.File]::ReadAllText($doctorPs);$start=$text.IndexOf('function Finish {');$stack=$text.IndexOf('[CANT-VERIFY] Agent-host stack toolchain');$summary=$text.IndexOf('Script-verifiable checks:');$finish=$text.Substring($start,$stack-$start);$m=[regex]::Match($finish,'Claude hooks - .*starts with "([^"]+)"');Assert $m.Success 'session quote';$hooks=(Resolve-Path(Join-Path $scripts '..\.claude\hooks')).Path;Assert([IO.File]::ReadAllText((Join-Path $hooks session-start.ps1)).Contains($m.Groups[1].Value))'session mismatch';$m=[regex]::Match($text,'hook says "([^"]+)"');Assert $m.Success 'guard quote';Assert([IO.File]::ReadAllText((Join-Path $hooks guard.ps1)).Contains($m.Groups[1].Value))'guard mismatch';Assert($stack-lt$summary-and$text.Contains('make and then revert')-and$text.Contains('post-write throttle'))'stack canary';Assert($text.Contains('## mvn test-compile failed')-and$text.Contains('## gradle testClasses failed'))'prefixes';$post=Join-Path $hooks 'post-write.ps1';if(-not(Test-Path -LiteralPath $post)){$post=Join-Path(Resolve-Path(Join-Path $scripts '..\..\..')).Path 'src/stacks/java/files/.claude/hooks/post-write.ps1'};Assert(Test-Path -LiteralPath $post)'post-write absent';$hookText=[IO.File]::ReadAllText($post);Assert($hookText.Contains('## mvn test-compile failed')-and$hookText.Contains('## gradle testClasses failed'))"$post"}
exit(Write-TestSummary 'FrameworkDoctor.Tests')
